import React from 'react';

export default function Header({ portal, setPortal, voiceOn, setVoiceOn }) {
  return (
    <header className="st-header">
      <div className="st-brand">
        <span className="st-brand-icon" aria-hidden="true">🛡️</span>
        <span className="st-brand-name">SafeTrace</span>
      </div>

      <nav className="st-portal-switch" role="tablist" aria-label="Portal selector">
        <button
          role="tab"
          aria-selected={portal === 'survivor'}
          className={`st-portal-btn ${portal === 'survivor' ? 'active' : ''}`}
          onClick={() => setPortal('survivor')}
        >
          Survivor Portal
        </button>
        <button
          role="tab"
          aria-selected={portal === 'admin'}
          className={`st-portal-btn ${portal === 'admin' ? 'active' : ''}`}
          onClick={() => setPortal('admin')}
        >
          ICC Command Center
        </button>
      </nav>

      <button
        className={`st-voice-toggle ${voiceOn ? 'active' : ''}`}
        onClick={() => setVoiceOn((v) => !v)}
        aria-pressed={voiceOn}
        title="Toggle hands-free voice guide"
      >
        🎤 Voice Guide
      </button>
    </header>
  );
}
